import { date, index, integer, pgTable, serial, text, timestamp, uuid } from "void/schema-pg";

export const messages = pgTable("messages", {
  id: serial("id").primaryKey(),
  text: text("text").notNull(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

// ── Identity ────────────────────────────────────────────────────────────────
// Account = Better Auth's `user` table (ADR 0003). Its tables are generated by
// Void, not declared here, so `account_id` columns hold `user.id` without a
// foreign key. Erasure deletes these rows explicitly.

/** The human whose records these are. Exactly one per Account in v1. */
export const persons = pgTable("persons", {
  id: uuid("id").primaryKey().defaultRandom(),
  accountId: text("account_id").notNull().unique(),
  name: text("name").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

/** Email addresses permitted to create an Account while sign-up is closed. */
export const allowlist = pgTable("allowlist", {
  email: text("email").primaryKey(),
  addedAt: timestamp("added_at", { withTimezone: true }).notNull().defaultNow(),
});

/** The Account's own list of sign-ins, failed attempts and credential changes. */
export const signInEvents = pgTable(
  "sign_in_events",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    accountId: text("account_id").notNull(),
    kind: text("kind").notNull(),
    device: text("device").notNull(),
    occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("sign_in_events_account_occurred_idx").on(t.accountId, t.occurredAt)],
);

/** How many Erasures happened on each day. No identifiers. */
export const erasureCounts = pgTable("erasure_counts", {
  day: date("day").primaryKey(),
  count: integer("count").notNull().default(0),
});
